/**
 * «Термінал Доглядача» in Foundry: the HTML terminal's four generators (Справа, Подорож, Натхнення, Битви).
 * The generators are the HTML terminal's own code (rules/terminal.mjs, generated by tools/port_terminal.py);
 * this window draws them, keeps the results (per user) and sends them to chat. «Битви» can also create the
 * enemies, place their tokens and start a combat (terminal-battle.mjs).
 */
import { addHelpButton } from "../tours/help-button.mjs";
import { CASE_DIFF, caseBattle, caseKind, casePower } from "../rules/case-battle.mjs";
import { travelDamage } from "./battle-panel.mjs";
import { sharedGet, sharedSet, travelToScene } from "../helpers/scene-shared.mjs";
import { createTerminal } from "../rules/terminal.mjs";
import { createBattle, openGeneratedEnemy, generatedEnemyImg, dropGeneratedEnemy, dropCompendiumEnemy, isCompendiumEnemyDrop, OPPONENT_ALIASES } from "./terminal-battle.mjs";
import { concreteKinds, namePicks } from "../rules/enemy-kinds.mjs";
import { postChat } from "./chat.mjs";
import { postTerminalRoll } from "./check-panel.mjs";
import { luckCaravan } from "./map-dice.mjs";
import {
  TABLE_CARDS, battleChat, battleJournal, blankTerminal, buildTerminalView, caseChat, caseJournal, runTable, tableChat, travelChat,
} from "./terminal-view.mjs";
import { notify } from "../helpers/notify.mjs";

const { ApplicationV2, HandlebarsApplicationMixin } = foundry.applications.api;
const FLAG = "terminal";
const CONFIRM_MS = 3000;
const clone = (o) => (o == null ? o : JSON.parse(JSON.stringify(o)));

let OPEN = null;
/** Open the terminal (Доглядач only) */
export function openTerminal() {
  if (!game.user.isGM) return notify.warn("Термінал — для Доглядача.");
  const first = !OPEN;
  OPEN ??= new TerminalApp();
  OPEN.render({ force: true, ...(first ? { position: freeSpot() } : {}) });
  return OPEN;
}

/** «Створити битву» in the «Подорож» window of «Мапа Пустки» (author, 2026-11-14): the terminal opens on «Битви» with that battle */
export function battleFromTravel(travel, i) {
  if (!game.user.isGM) return;
  const first = !OPEN;
  OPEN ??= new TerminalApp();
  if (OPEN.fromTravel(travel, i) === false) return;
  OPEN.render({ force: true, ...(first ? { position: freeSpot() } : {}) });
  OPEN.bringToFront?.();
}

/**
 * «Почати бій» under a travel battle (author, 2026-11-16): the battle goes to «Битви» as «Створити битву» does, then the battle
 * map is activated (the players come along) and its enemies are put into its zones — the battle's own (a scripted one) or
 * rolled by the battle generator (a random one).
 */
export async function startTravelBattle(travel, i) {
  if (!game.user.isGM) return;
  OPEN ??= new TerminalApp();
  if (OPEN.fromTravel(travel, i) === false) return;
  return startBattle();
}

/** «Почати бій» (the battle generator's too, author 2026-11-16): the battle map activated, the terminal's battle placed there */
export async function startBattle() {
  if (!game.user.isGM || !OPEN?.st?.battle?.state?.last) return;
  const { battleScene } = await import("./battle-panel.mjs");
  const scene = battleScene();
  if (!scene) return notify.warn("У світі немає бойової мапи. Створи сцену типу «Битва».");
  // its background by the battle's place first, while nobody views it: one redraw (author, 2026-11-18)
  const { syncBattleBackground } = await import("../helpers/battle-background.mjs");
  await syncBattleBackground(scene, OPEN.T.battle.BT?.BT_SCENE?.place || sharedGet("place"));
  // its weather by the battle's hazard («Авто-погода», author, 2026-11-19), before the players come
  await (await import("../canvas/weather.mjs")).syncHazardWeather(scene, OPEN.T.battle.BT?.BT_SCENE?.hazard || sharedGet("hazard"));
  if (canvas?.scene?.id !== scene.id) {
    const ready = new Promise((r) => Hooks.once("canvasReady", r));
    await scene.activate();
    await ready;
  } else if (!scene.active) await scene.activate();
  await createBattle(OPEN.T, OPEN.st, "place");
  if (OPEN.rendered) OPEN.render();
}

/**
 * Where the terminal opens the first time (author, 2026-11-14): in the free space — right of the scene navigation,
 * under the «Термінал Доглядача» plate, left of the sidebar — so it covers neither the scene list nor the controls.
 */
function freeSpot() {
  const right = (sel) => Math.max(0, ...[...document.querySelectorAll(sel)].map((e) => e.getBoundingClientRect().right));
  const bottom = (sel) => Math.max(0, ...[...document.querySelectorAll(sel)].map((e) => e.getBoundingClientRect().bottom));
  const gap = 12;
  const left = Math.round(Math.max(right("#scene-controls"), right("#scene-navigation li.scene")) + gap);
  const top = Math.round(Math.max(bottom(".wastelanders-terminal-dock"), bottom("#scene-navigation-viewed")) + gap);
  const sidebar = document.querySelector("#sidebar")?.getBoundingClientRect().left || window.innerWidth;
  const width = Math.max(560, Math.min(860, Math.round(sidebar - gap - left)));
  const height = Math.max(420, Math.min(820, Math.round(window.innerHeight - top - gap)));
  return { left, top, width, height };
}

// «Подорож» shows (and takes) the selected caravan's Удача партії: redraw when the selection changes
const travelLuckRedraw = foundry.utils.debounce(() => { if (OPEN?.rendered && OPEN.st?.tab === "travel") OPEN.render(); }, 100);
Hooks.on("controlToken", travelLuckRedraw);

/** The plate «Термінал Доглядача» (author, 2026-11-14): opens the terminal, a second press closes it */
export function toggleTerminal() {
  if (OPEN?.rendered) return OPEN.close();
  return openTerminal();
}

/** Light the plate while the terminal is open */
const markPlate = (on) => document.querySelectorAll(".wastelanders-terminal-open").forEach((b) => b.classList.toggle("on", on));

/** The right sidebar on the Actors tab with a folder and its parents unfolded, scrolled to it */
async function revealFolder(folder) {
  if (!folder) return;
  for (let f = folder; f; f = f.folder) game.folders._expanded[f.uuid] = true;
  ui.sidebar.expand();
  ui.sidebar.changeTab("actors", "primary");
  await ui.actors.render();
  setTimeout(() => ui.actors.element?.querySelector(`[data-folder-id="${folder.id}"], [data-uuid="${folder.uuid}"]`)?.scrollIntoView({ block: "start" }), 300);
}

/** A «Битви» chip dropped on the canvas: its enemy's token there */
const DROP_TYPE = "PustGeneratedEnemy";
Hooks.on("dropCanvasData", (cv, data) => {
  if (data?.type !== DROP_TYPE) return;
  const app = foundry.applications.instances.get("pust-terminal");
  if (app) dropGeneratedEnemy(app.T, app.st, data.name, { x: data.x, y: data.y });
  return false;
});

/** An enemy dragged from a compendium onto the scene (author, 2026-11-19): the GM's goes to «Битви» as the «Битва» panel's */
Hooks.on("dropCanvasData", (cv, data, event) => {
  if (!game.user.isGM || !isCompendiumEnemyDrop(data, fromUuidSync(data?.uuid ?? "", { strict: false }))) return;
  if (!canvas.dimensions.rect.contains(data.x, data.y)) return false;
  dropCompendiumEnemy(data, { hidden: !!event?.altKey });
  return false;
});

class TerminalApp extends HandlebarsApplicationMixin(ApplicationV2) {
  static DEFAULT_OPTIONS = {
    id: "pust-terminal",
    classes: ["wastelanders", "pust-terminal-app"],
    position: { width: 860, height: 820 },
    window: { title: "Термінал Доглядача", icon: "fa-solid fa-terminal", resizable: true },
    actions: {
      termTab: TerminalApp.#on((app, t) => { app.st.tab = t.dataset.tab; }),
      caseDiff: TerminalApp.#on((app, t) => { app.st.case.diff = t.dataset.diff; if (app.st.case.cs) app.st.case.cs = clone(app.T.case.setDifficulty(t.dataset.diff)); else app.T.case.setDifficulty(t.dataset.diff); }),
      caseGen: TerminalApp.#on((app) => { app.st.case.cs = clone(app.T.case.generate(app.st.case.diff)); }),
      caseReroll: TerminalApp.#on((app, t) => { app.st.case.cs = clone(app.T.case.reroll(t.dataset.k)); }),
      travelType: TerminalApp.#on((app, t) => { app.st.travel.type = t.dataset.type; }),
      travelLuck: TerminalApp.#on((app, t) => { app.st.travel.luck = Number(t.dataset.luck); }),
      travelGen: TerminalApp.#on((app) => { Object.assign(app.st.travel, app.T.travel.generate(app.st.travel.type, app.st.travel.luck)); travelToScene(app.st.travel.main, app.st.travel.additional); }),
      travelKinds: TerminalApp.#on((app, t) => app.#travelKinds(+t.dataset.i)),
      travelBattle: TerminalApp.#on((app, t) => app.#travelBattle(+t.dataset.i)),
      travelFight: TerminalApp.#on((app, t) => { startTravelBattle(clone(app.st.travel), +t.dataset.i); return false; }),
      battleFight: TerminalApp.#on(() => { startBattle(); return false; }),
      caseBattle: TerminalApp.#on((app) => app.#caseBattle()),
      tableGen: TerminalApp.#on((app, t) => {
        const card = TABLE_CARDS.find((c) => c.id === t.dataset.card);
        app.st.tables.out[card.id] = runTable(app.T, card, app.st.tables.sel);
      }),
      battleGen: TerminalApp.#on((app) => app.#battle((B) => B.generate(app.st.battle.difficulty, app.st.battle.kinds), true)),
      battleScene: TerminalApp.#on((app, t) => app.#battle((B) => B.rollScene(t.dataset.kind))),
      battleReward: TerminalApp.#on((app) => app.#battle((B) => B.rollReward())),
      battleEnemy: TerminalApp.#onEnemy,
      battleClear: TerminalApp.#on((app, t) => {
        if (!TerminalApp.#armed(t)) return false;
        app.st.battle.state = null; app.st.battle.names = [];
        app.T = null; // a fresh generator: the cleared battle is gone from it too
      }),
      battleCreate: TerminalApp.#onCreate,
      toChat: TerminalApp.#onChat,
      toJournal: TerminalApp.#onJournal,
      die: TerminalApp.#onDie,
    },
  };

  static PARTS = { main: { template: "systems/wastelanders-dev/templates/apps/terminal.hbs", scrollable: [".pust-term-body"] } };

  /** UI state not saved */
  ui = {};

  /** The saved terminal (per user) */
  get st() {
    this._st ??= foundry.utils.mergeObject(blankTerminal(), clone(game.user.getFlag(game.system.id, FLAG)) || {}, { inplace: false });
    return this._st;
  }

  /** The generators, with the saved results loaded into them */
  get T() {
    if (!this._T) {
      const T = createTerminal({ toast: (m) => notify.info(m), icon: (n) => `<i class="pust-pi pi-${n}"></i>` });
      const st = this.st;
      T.case.setDifficulty(st.case.diff);
      if (st.case.cs) T.case.set(clone(st.case.cs));
      T.battle.setDifficulty(st.battle.difficulty);
      T.battle.setKinds(st.battle.kinds);
      if (st.battle.state) T.battle.restore(clone(st.battle.state));
      this._T = T;
    }
    return this._T;
  }
  set T(v) {
    this._T = v;
  }

  #saveTimer = null;
  save() {
    clearTimeout(this.#saveTimer);
    this.#saveTimer = setTimeout(() => game.user.setFlag(game.system.id, FLAG, clone(this.st)), 300);
  }

  /** A handler that changes the state, then saves and redraws (return false to skip) */
  static #on(fn) {
    return async function (event, target) {
      if ((await fn(this, target, event)) === false) return;
      this.save();
      this.render();
    };
  }

  static #armed(target) {
    if (target.classList.contains("armed")) return true;
    target.classList.add("armed");
    notify.info("Натисни ще раз, щоб підтвердити.");
    setTimeout(() => target.classList.remove("armed"), CONFIRM_MS);
    return false;
  }

  #battle(fn, fresh = false) {
    const B = this.T.battle;
    B.setDifficulty(this.st.battle.difficulty);
    B.setKinds(this.st.battle.kinds);
    if (fresh && !this.st.battle.kinds.length) return notify.warn("Обери щонайменше один вид супротивників.");
    // the place and hazard are the panels' ones, shared by every scene (author, 2026-11-16): in, and back out when rerolled
    B.BT.BT_SCENE.place = sharedGet("place") || "";
    B.BT.BT_SCENE.hazard = sharedGet("hazard") || "";
    const s = fn(B);
    if ((s.place || "") !== (sharedGet("place") || "") || (s.hazard || "") !== (sharedGet("hazard") || "")) sharedSet({ place: s.place || "", hazard: s.hazard || "" });
    if (fresh) { this.st.battle.names = []; this.st.battle.picks = {}; }
    // a group enemy («Маленькі тварини…») becomes one concrete kind, kept through rerolls (author, 2026-11-16)
    this.st.battle.picks ??= {};
    this.st.battle.state = concreteKinds(clone({ ...s, names: undefined }), this.st.battle.picks, OPPONENT_ALIASES);
  }

  /* ---------- travel battles: reroll the kinds, or move the battle to «Битви» ---------- */

  #travelSection(i) {
    const div = document.createElement("div");
    div.innerHTML = this.st.travel.additional;
    return { div, sec: div.querySelectorAll(".battle-encounter")[i] };
  }

  /**
   * «Створити битву» under the case's «Супротивники» (author, 2026-11-17): the battle generator gets the case's battle — its
   * group as a kind (rules/case-battle.mjs CASE_KINDS), its «Міць супротивників» as exact counts, its difficulty — and the
   * terminal turns to «Битви» with it
   */
  #caseBattle() {
    const cs = this.st.case.cs;
    if (!cs) return false;
    const B = this.T.battle;
    const kind = caseKind(cs.f.enemies);
    const diff = CASE_DIFF[cs.diff] || "easy";
    B.setDifficulty(diff);
    const b = caseBattle(B.BT.DB, B.BT.ORDER, kind, casePower(cs.f.enemyPower));
    if (!b) return notify.warn("Не вдалося зібрати битву з цієї справи."), false;
    B.BT.BT_SCENE.place = sharedGet("place") || "";
    B.BT.BT_SCENE.hazard = sharedGet("hazard") || "";
    B.BT.renderBattle(b.factionKey, b.pickedCase, b.allocations);
    const s = B.state();
    this.st.battle.difficulty = diff;
    this.st.battle.kinds = [kind];
    this.st.battle.names = [];
    this.st.battle.picks = {};
    this.st.battle.state = concreteKinds(clone({ ...s, names: undefined }), this.st.battle.picks, OPPONENT_ALIASES);
    this.st.tab = "battle";
    notify.info(`Битву зі справи перенесено на вкладку «Битви»: ${B.BT.kindName(kind)}, ${cs.f.enemyPower}.`);
  }

  #travelKinds(i) {
    const { div, sec } = this.#travelSection(i);
    const span = sec?.querySelector(".tvb-rnd");
    if (!span) return false;
    const ks = this.T.travel.kindsRoll((span.dataset.kinds || "").split(",").filter(Boolean));
    span.dataset.kinds = ks.join(",");
    span.innerHTML = this.T.travel.randomText(ks);
    this.st.travel.additional = div.innerHTML;
  }

  #travelBattle(i) {
    const { sec } = this.#travelSection(i);
    const span = sec?.querySelector(".tvb");
    if (!span) return false;
    const place = sec.querySelector(".tv-place")?.textContent || "";
    const spec = span.dataset.kinds
      ? { diff: span.dataset.diff, kinds: span.dataset.kinds.split(",").filter(Boolean), place }
      : { diff: span.dataset.diff, idx: +span.dataset.idx, place };
    const s = this.T.battle.fromTravel(spec);
    if (!s) return notify.warn("Не вдалося зібрати цю битву."), false;
    sharedSet({ place: s.place || "", hazard: s.hazard || "" }); // the travel's place becomes the battle's, on every scene
    this.st.battle.difficulty = s.difficulty;
    this.st.battle.names = s.names || [];
    // the names say the kind: «Рейдер 3» is a Рейдер, and the crowd's leader and boss follow (author, 2026-11-19)
    this.st.battle.picks = namePicks(s.last?.allocations, s.names, OPPONENT_ALIASES);
    this.st.battle.state = concreteKinds(clone({ ...s, names: undefined }), this.st.battle.picks, OPPONENT_ALIASES);
    this.st.tab = "battle";
    notify.info("Битву з подорожі перенесено на вкладку «Битви».");
  }

  /** A battle of a travel event made elsewhere (the «Подорож» window of «Мапа Пустки»): that event becomes the terminal's, its battle goes to «Битви» */
  fromTravel(travel, i) {
    Object.assign(this.st.travel, clone(travel));
    if (this.#travelBattle(i) === false) return false;
    this.save();
    return true;
  }

  /* ---------- buttons with their own work ---------- */

  static async #onCreate(event, target) {
    target.disabled = true;
    try {
      const made = await createBattle(this.T, this.st, target.dataset.mode);
      // «Додати теку в Актори» (author, 2026-11-16): the Actors tab open, the battle's folder unfolded
      if (target.dataset.mode === "folder" && made?.length) revealFolder(made[0].folder);
    } finally {
      target.disabled = false;
    }
  }

  /** A chip of «Битви» (author, 2026-11-16): the enemy's card */
  static async #onEnemy(event, target) {
    await openGeneratedEnemy(this.T, this.st, target.dataset.name);
  }

  static async #onChat(event, target) {
    const st = this.st;
    const html = { case: () => caseChat(st), travel: () => travelChat(st), table: () => tableChat(st, target.dataset.card), battle: () => battleChat(this.T, st) }[target.dataset.what]?.();
    if (!html) return;
    const data = { content: html, speaker: ChatMessage.getSpeaker({ alias: "Термінал Доглядача" }) };
    await postChat(data);
  }

  /** «В журнал»: the case or the battle as a new journal entry in the folder «Термінал Доглядача», opened at once */
  static async #onJournal(event, target) {
    const j = { case: () => caseJournal(this.st), battle: () => battleJournal(this.T, this.st) }[target.dataset.what]?.();
    if (!j) return;
    const FOLDER = "Термінал Доглядача";
    const folder = game.folders.find((f) => f.type === "JournalEntry" && f.name === FOLDER && !f.folder)
      || await Folder.create({ name: FOLDER, type: "JournalEntry", color: "#9a4a20" });
    const entry = await JournalEntry.create({ name: j.name, folder: folder.id, pages: [{ name: j.name, type: "text", text: { content: j.html } }] });
    notify.info(`Записано в журнал: «${entry.name}»`);
    entry.sheet.render(true);
  }

  /** A die in the results («2d6»): rolled by Foundry and posted to chat */
  static async #onDie(event, target) {
    const expr = target.dataset.dice;
    if (!expr) return;
    // on «Подорож» a hazard's damage («3d6 шкоди») goes into «Сцена» / «Битва», lit there (author, 2026-11-16)
    if (target.closest(".pust-travel")) {
      const { fillDamage } = await import("./battle-panel.mjs");
      const dmg = travelDamage(target);
      if (dmg) return fillDamage(dmg);
    }
    await postTerminalRoll(expr); // the dice card, as «Кістки» (follows the chat's mode menu)
  }

  /* ---------- drawing ---------- */

  async _prepareContext() {
    // «Подорож»: Удача партії comes from the selected caravan token, or the only caravan on the scene (as the HTML map's
    // travel float, author 2026-11-14). It is applied when that caravan or its luck changes, so a hand-picked value stays
    // until then; the screen says where the luck came from.
    const car = luckCaravan();
    const t = this.st.travel;
    let luckCar = null;
    if (car) {
      const l = parseInt(car.system.luck, 10) || 0;
      const v = Math.max(-2, Math.min(2, l));
      const from = `${car.id}:${l}`;
      if (t.luckFrom !== from) { t.luck = v; t.luckFrom = from; }
      luckCar = { name: car.name, luck: l > 0 ? `+${l}` : l < 0 ? `−${-l}` : "0", clipped: v !== l, used: Number(t.luck) === v };
    } else t.luckFrom = "";
    const v = buildTerminalView(this.T, this.st, this.ui);
    v.travel.luckCar = luckCar;
    return { v };
  }

  _onRender(context, options) {
    super._onRender(context, options);
    // «?» (author, 2026-11-17): the terminal's tour, at the tab now open
    addHelpButton(this, () => ["gm-terminal", this.st.tab || "case"]);
    const root = this.element;
    // «Битви»: each chip's token picture (author, 2026-11-16)
    root.querySelectorAll("img.pust-enchip-tok[data-tok]").forEach(async (img) => { img.src = await generatedEnemyImg(img.dataset.tok, img.dataset.group); });
    // …and each chip may be dragged onto the scene (author, 2026-11-16; the drop: the dropCanvasData hook above the class)
    root.querySelectorAll(".pust-enchip[draggable]").forEach((b) => b.addEventListener("dragstart", (ev) => {
      ev.dataTransfer.setData("text/plain", JSON.stringify({ type: DROP_TYPE, name: b.dataset.name }));
      const img = b.querySelector("img");
      if (img) ev.dataTransfer.setDragImage(img, 15, 15);
    }));
    // dice from the generators' HTML: <button class="die" data-dice="2d6">
    root.querySelectorAll("button.die").forEach((b) => { b.type = "button"; b.dataset.action = "die"; b.title = `Кинути ${b.dataset.dice}`; });
    // on «Подорож» a hazard's damage die goes into the panel (author, 2026-11-16)
    root.querySelectorAll(".pust-travel button.die").forEach((b) => { if (travelDamage(b)) { b.title = "Перенести в «Шкода й лікування» панелі"; b.classList.add("pust-die-dmg"); } });
    // travel battles: «Перекинути види» and «Створити битву» (the HTML terminal's tvEnhance)
    root.querySelectorAll(".pust-travel .battle-encounter").forEach((sec, i) => {
      const span = sec.querySelector(".tvb");
      if (!span) return;
      const btns = document.createElement("div");
      btns.className = "pust-tvb-actions";
      btns.innerHTML = (span.classList.contains("tvb-rnd")
        ? `<button type="button" data-action="travelKinds" data-i="${i}" title="Перекинути випадкову битву: інші види супротивників"><i class="fa-solid fa-rotate"></i> Інші види</button>`
        : "")
        + `<button type="button" class="pust-term-go" data-action="travelBattle" data-i="${i}" title="Перенести битву й місце на вкладку «Битви»"><i class="fa-solid fa-skull"></i> Створити битву</button>`
        + `<button type="button" class="pust-term-go pust-tvb-fight" data-action="travelFight" data-i="${i}" title="Перейти на бойову мапу, активувати її (гравці теж перейдуть) і розставити супротивників цієї битви по зонах"><i class="fa-solid fa-flag"></i> Почати бій</button>`
        + `<span class="pust-sub">${span.classList.contains("tvb-rnd") ? "Склад супротивників кинеться за правилами генератора битв." : "Кількість супротивників кинеться за описом битви."} Місце піде у вкладку «Битви».</span>`;
      sec.append(btns);
    });
    // selects and checkboxes of the tabs
    root.querySelectorAll("[data-k]").forEach((el) => el.addEventListener("change", () => {
      const k = el.dataset.k;
      if (k.startsWith("tables.")) this.st.tables.sel[k.slice(7)] = el.value;
      else if (k === "battle.difficulty") this.st.battle.difficulty = el.value;
      else if (k === "battle.kind") {
        const ks = this.st.battle.kinds.filter((x) => x !== el.value);
        if (el.checked) ks.push(el.value);
        this.st.battle.kinds = this.T.battle.kinds().map((x) => x.key).filter((x) => ks.includes(x));
      }
      this.save();
      this.render();
    }));
  }

  _onFirstRender(context, options) {
    super._onFirstRender(context, options);
    markPlate(true);
  }

  _onClose(options) {
    super._onClose(options);
    markPlate(false);
    clearTimeout(this.#saveTimer);
    game.user.setFlag(game.system.id, FLAG, clone(this.st));
  }
}
